import { HtmlLayeredBackground } from "../../../../common/html";
import { SceneEvents } from "../../../../common/events";
import { onSceneShutdown } from "../../../../common/scenes";
import { GameServiceProvider } from "../../../../services";
import { ISpiderGameBackground } from "../../../../logic";
import { themeConfig } from "../../../../config.themes";
import { IGameEvents } from "../../../events";

interface IProps {
  scene: Phaser.Scene;
  isColorOverlay?: boolean;
}

/** Выбирает и применяет фон сцены из GameService. */
export class BgAssetManager {
  private readonly sceneEvents: SceneEvents<IGameEvents>;
  private bg: HtmlLayeredBackground | undefined;

  constructor(private readonly props: IProps) {
    this.initBackground();
    this.sceneEvents = new SceneEvents<IGameEvents>({ scene: this.props.scene });
    onSceneShutdown(this.props.scene, () => this.destroy());
    this.sceneEvents.on("setSceneBg", ({ url, fallbackUrl }) => {
      this.saveBackground(url, fallbackUrl);
      this.applyBackground(url, fallbackUrl);
    });
    this.sceneEvents.on("setBgOpacity", ({ opacity }) => {
      this.saveOpacity(opacity);
      this.reapplyBackground();
    });
  }

  private initBackground() {
    const gameService = GameServiceProvider.get();
    const playerData = gameService.getPlayerData();
    const spiderBackground = playerData.gameBackground;
    const defaultBackgroundUrl = themeConfig.backgrounds[0].imageUrl.url;
    const backgroundUrl = spiderBackground?.backgroundUrl ?? defaultBackgroundUrl;
    const backgroundUrlFallback = spiderBackground?.backgroundUrlFallback;

    if (spiderBackground == null) {
      const nextSpiderBackground: ISpiderGameBackground = {
        backgroundUrl: defaultBackgroundUrl,
        backgroundUrlFallback: undefined,
      };

      gameService.setPlayerData({
        gameBackground: nextSpiderBackground,
      });
    }

    this.applyBackground(backgroundUrl, backgroundUrlFallback);
  }

  private saveBackground(url: string, fallbackUrl?: string) {
    const gameService = GameServiceProvider.get();
    const playerData = gameService.getPlayerData();
    const nextSpiderBackground: ISpiderGameBackground = {
      backgroundUrl: url,
      backgroundUrlFallback: fallbackUrl,
    };

    gameService.setPlayerData({
      gameBackground: nextSpiderBackground,
    });
  }

  private saveOpacity(opacity: number) {
    const gameService = GameServiceProvider.get();

    gameService.setPlayerData({
      /** Opacity сохраняется в плоском GamePlayerData и сразу применяется к текущему HtmlLayeredBackground. **/
      gameBgUrlOverlayOpacity: clampBackgroundBrightness(opacity),
    });
  }

  private reapplyBackground() {
    const gameService = GameServiceProvider.get();
    const playerData = gameService.getPlayerData();
    const defaultBackgroundUrl = themeConfig.backgrounds[0].imageUrl.url;
    const background = playerData.gameBackground;

    this.applyBackground(
      background?.backgroundUrl ?? defaultBackgroundUrl,
      background?.backgroundUrlFallback,
    );
  }

  private applyBackground(url: string, fallbackUrl?: string) {
    const defaultBackgroundUrl = themeConfig.backgrounds[0].imageUrl.url;
    const opacity = clampBackgroundBrightness(GameServiceProvider.get().getPlayerData().gameBgUrlOverlayOpacity);

    this.bg?.destroy();
    this.bg = new HtmlLayeredBackground({
      layers: this.props.isColorOverlay
        ? [
            { backgroundCss: themeConfig.backgroundOverlay.backgroundCss },
            {
              url,
              fallbackUrl,
              defaultUrl: defaultBackgroundUrl,
              opacity,
            },
          ]
        : [{ url, fallbackUrl, defaultUrl: defaultBackgroundUrl }],
    });
  }

  private destroy() {
    this.sceneEvents.unSubscribeAll();
    this.bg?.destroy();
    this.bg = undefined;
  }
}

function clampBackgroundBrightness(opacity: number): number {
  return Math.min(1, Math.max(0.1, opacity));
}
