import type {GamePlayerData, IShopConfig} from './logic';

/** сколько начисляем за каждую покупку **/
const shopItemGoldMap = {
    packetOfGold: 10,
    common: 60,
    silver: 125,
    gold: 249,
} as const;

type ShopItemId = keyof typeof shopItemGoldMap;

/** пока по**/
const rewardItemIds = [
    'packetOfGold'
] as const;

/** Должны совпадать с id в API!!! **/
const buyItemIds = [
    'common', 'silver', 'gold'
] as const;

export type InAppPurchaseId = typeof buyItemIds[number];
export type RewardPurchaseId = typeof rewardItemIds[number];
export type PurchaseId = InAppPurchaseId | RewardPurchaseId;

export const shopConfig: IShopConfig = {
    shopItemsOrdered: {
        rewardItemIds: [...rewardItemIds],
        buyItemIds: [...buyItemIds],
    },
    /** конвертер id покупки в состояние игрока **/
    addShopItemToState: (shopItemId, prevPlayerData) => {
        const prev = prevPlayerData as GamePlayerData;
        const {gold} = getShopItemData(shopItemId);

        if (gold <= 0) return {
            ...prev
        }

        return {
            ...prev,
            gold: prev.gold + gold,
        }
    },
    getShopItemData
} as const;


function getShopItemData(shopItemId: string): {  gold: number } {
    const gold = shopItemGoldMap[shopItemId as ShopItemId] ?? 0;
    return {gold};
}
