import {
    FloatingTextEffect,
    ImageBurstEffect,
    ImageEffectPool,
    ImageFlyEffect,
    SceneEvents,
    TextEffectPool,
} from "../../../common";
import {assetsViewsAutoAssets} from "../../auto_generated/assets-views-assets";
import {IGameEvents} from "../../events";
import {defaultMoneyEffectLayerConfig} from "./config";
import {
    IMoneyEffectLayerConfig,
    IMoneyEffectLayerConfigInput,
    IMoneyGainEffectPayload,
    IMoneySpendEffectPayload,
    IMoneyTextEffectConfig,
} from "./types";

const MONEY_EFFECT_LAYER_DEPTH = 10000;

/**
 * Слой визуальных денежных эффектов.
 *
 * Живет отдельно от UI, слушает scene events с глобальными координатами и
 * перед каждым эффектом поднимает себя наверх. Высокий depth защищает от
 * обычных UI-элементов, а bringToTop помогает после создания оверлеев.
 **/
export class MoneyEffectLayer extends Phaser.GameObjects.Container {
    private readonly unSubs: Array<() => void> = [];
    private readonly activeEffects = new Set<{ destroy: () => void }>();
    private readonly config: IMoneyEffectLayerConfig;
    private readonly coinPool: ImageEffectPool;
    private readonly textPool: TextEffectPool;

    constructor(scene: Phaser.Scene, config?: IMoneyEffectLayerConfigInput) {
        super(scene, 0, 0);

        this.config = {
            ...defaultMoneyEffectLayerConfig,
            ...config,
            spend: {
                ...defaultMoneyEffectLayerConfig.spend,
                ...config?.spend,
                text: {
                    ...defaultMoneyEffectLayerConfig.spend.text,
                    ...config?.spend?.text,
                },
            },
            gain: {
                ...defaultMoneyEffectLayerConfig.gain,
                ...config?.gain,
                text: {
                    ...defaultMoneyEffectLayerConfig.gain.text,
                    ...config?.gain?.text,
                },
            },
        };

        const events = new SceneEvents<IGameEvents>({scene, autoUnSub: this});
        this.unSubs.push(events.on("moneySpendEffectRequest", (data) => this.showSpend(data)));
        this.unSubs.push(events.on("moneyGainEffectRequest", (data) => this.showGain(data)));

        scene.add.existing(this);
        this.setDepth(MONEY_EFFECT_LAYER_DEPTH);
        this.coinPool = new ImageEffectPool({
            scene,
            parent: this,
            asset: assetsViewsAutoAssets.coin40,
            initialSize: Math.max(this.config.spend.particleCount, this.config.gain.particleCount),
        });
        this.textPool = new TextEffectPool({
            scene,
            parent: this,
            initialSize: 3,
        });
        this.bringLayerToTop();
    }

    destroy(fromScene?: boolean): void {
        this.unSubs.forEach((unSub) => unSub());
        this.unSubs.length = 0;
        this.activeEffects.forEach((effect) => effect.destroy());
        this.activeEffects.clear();
        this.coinPool.destroy();
        this.textPool.destroy();
        super.destroy(fromScene);
    }

    private showSpend(data: IMoneySpendEffectPayload): void {
        this.bringLayerToTop();
        let burstEffect: ImageBurstEffect;
        burstEffect = new ImageBurstEffect({
            scene: this.scene,
            asset: assetsViewsAutoAssets.coin40,
            pool: this.coinPool,
            startPoint: data.clickPoint,
            config: {
                amount: this.config.spend.particleCount,
                scaleMin: this.config.spend.scaleMin,
                scaleMax: this.config.spend.scaleMax,
                scaleMultiplier: this.config.spend.scaleMultiplier,
                speedMin: this.config.spend.speedMin,
                speedMax: this.config.spend.speedMax,
                gravity: this.config.spend.gravity,
                duration: this.config.spend.duration,
                fadeStartK: this.config.spend.fadeStartK,
                angleStart: this.config.spend.angleStart,
                angleEnd: this.config.spend.angleEnd,
            },
            onComplete: () => this.removeEffect(burstEffect),
        });
        this.addEffect(burstEffect);
        this.addAmountText(`-${data.amount}`, data.clickPoint, this.config.spend.text);
    }

    private showGain(data: IMoneyGainEffectPayload): void {
        this.bringLayerToTop();
        this.addAmountText(`+${data.amount}`, data.clickPoint, this.config.gain.text);

        if (data.targetPoint == null) {
            return;
        }

        let flyEffect: ImageFlyEffect;
        flyEffect = new ImageFlyEffect({
            scene: this.scene,
            asset: assetsViewsAutoAssets.coin40,
            pool: this.coinPool,
            startPoint: data.clickPoint,
            targetPoint: data.targetPoint,
            config: {
                amount: this.config.gain.particleCount,
                scaleMin: this.config.gain.scaleMin,
                scaleMax: this.config.gain.scaleMax,
                burstDistance: this.config.gain.burstDistance,
                burstDuration: this.config.gain.burstDuration,
                flyStepMs: this.config.gain.flyStepMs,
                flyDurationMin: this.config.gain.flyDurationMin,
                flyDurationMax: this.config.gain.flyDurationMax,
                arcHeightMin: this.config.gain.arcHeightMin,
                arcHeightMax: this.config.gain.arcHeightMax,
                arcHeightK: this.config.gain.arcHeightK,
            },
            onComplete: () => this.removeEffect(flyEffect),
        });
        this.addEffect(flyEffect);
    }

    private addAmountText(text: string, clickPoint: { x: number; y: number }, config: IMoneyTextEffectConfig): void {
        let textEffect: FloatingTextEffect;
        textEffect = new FloatingTextEffect({
            scene: this.scene,
            pool: this.textPool,
            config: {
                text,
                startPoint: clickPoint,
                velocityX: 0,
                velocityY: config.velocityY,
                duration: config.duration,
                scaleFrom: config.scaleFrom,
                scaleTo: config.scaleTo,
                style: {
                    fontFamily: "\"Russo One\", Roboto, Verdana, sans-serif",
                    fontSize: config.fontSize,
                    color: config.color,
                    align: "center",
                    stroke: config.stroke,
                    strokeThickness: 6,
                },
            },
            onComplete: () => this.removeEffect(textEffect),
        });
        this.addEffect(textEffect);
    }

    private addEffect(effect: { destroy: () => void }): void {
        this.activeEffects.add(effect);
    }

    private removeEffect(effect: { destroy: () => void }): void {
        this.activeEffects.delete(effect);
    }

    private bringLayerToTop(): void {
        if (this.scene != null) {
            this.scene.children.bringToTop(this);
        }
    }
}
