import {SceneEvents} from "../../common";
import {ISceneDialogHandle, openSceneDialog} from "../../common/game-core";
import {isInAppPurchaseId, isRewardPurchaseId, PurchaseId} from "../../logic";
import {GameServiceProvider} from "../../services";
import {ButtonEvents} from "../auto_generated/addButtonViewInteractivity";
import {createViewGoldShop} from "../auto_generated/tuned";
import {getGoldShopData} from "../auto_generated/tuned/view-gold-logic";
import type {GoldShopViewData} from "../auto_generated/tuned/view-gold-logic";
import {IGameEvents} from "../events";

interface IProps {
    scene: Phaser.Scene;
}

const GOLD_SHOP_REWARD_BUTTON = "buttonGoldShopItemReward";
const GOLD_SHOP_BUY_BUTTONS = [
    "buttonGoldShopItemSmall",
    "buttonGoldShopItemMid",
    "buttonGoldShopItemBig",
] as const;

/**
 * Менеджер магазина голды.
 *
 * Открывает tuned view магазина в текущей сцене: без отдельной Phaser scene.
 * Данные и порядок товаров берутся из shop config.
 **/
export class GoldShopDialogManager extends Phaser.GameObjects.Zone {
    private readonly unSubs: Array<() => void> = [];
    private readonly sceneEvents: SceneEvents<IGameEvents>;
    private dialog?: ISceneDialogHandle;
    private currentShopData?: GoldShopViewData;
    private isPurchaseInProgress = false;

    constructor(private readonly props: IProps) {
        super(props.scene, 0, 0);
        this.sceneEvents = new SceneEvents<IGameEvents>({scene: props.scene});
        this.unSubs.push(this.sceneEvents.on("onShopButtonClick", () => this.openDialog()));
        this.unSubs.push(() => this.dialog?.destroy());
        props.scene.events.on(ButtonEvents.onClick, this.onButtonClick);
        this.unSubs.push(() => props.scene.events.off(ButtonEvents.onClick, this.onButtonClick));
    }

    destroy(fromScene?: boolean): void {
        this.unSubs.forEach((unSub) => unSub());
        this.unSubs.length = 0;
        this.dialog = undefined;
        super.destroy(fromScene);
    }

    private openDialog(): void {
        const {scene} = this.props;
        const shopData = getGoldShopData();

        if (shopData.reward == null && (shopData.shopItems?.length ?? 0) === 0) {
            return;
        }

        this.dialog?.destroy();
        this.currentShopData = shopData;
        this.dialog = openSceneDialog({
            scene,
            isCloseOnOverlayClick: true,
            createContent: ({scene}) => createViewGoldShop({scene, ...shopData}),
            onClose: () => {
                this.dialog = undefined;
                this.currentShopData = undefined;
            },
        });
    }

    private onButtonClick = ({gameObjectName}: { gameObjectName: string }): void => {
        if (this.dialog == null) {
            return;
        }

        if (gameObjectName === "buttonBack") {
            this.dialog.close();
            return;
        }

        const purchaseId = this.getPurchaseIdByButtonName(gameObjectName);
        if (purchaseId == null) {
            return;
        }

        void this.purchaseItem(purchaseId);
    };

    private getPurchaseIdByButtonName(buttonName: string): PurchaseId | undefined {
        if (buttonName === GOLD_SHOP_REWARD_BUTTON) {
            const rewardId = GameServiceProvider.get().getGameConfig().shop.shopItemsOrdered.rewardItemIds[0];
            return isRewardPurchaseId(rewardId) ? rewardId : undefined;
        }

        const buyButtonIndex = GOLD_SHOP_BUY_BUTTONS.findIndex((name) => name === buttonName);
        const buyItemId = this.currentShopData?.shopItems?.[buyButtonIndex]?.id;
        return isInAppPurchaseId(buyItemId) ? buyItemId : undefined;
    }

    private async purchaseItem(id: PurchaseId): Promise<void> {
        if (this.isPurchaseInProgress) {
            return;
        }

        this.isPurchaseInProgress = true;
        const shop = GameServiceProvider.get().shop;
        const isInAppPurchase = isInAppPurchaseId(id);
        if (shop == null) {
            console.warn("game shop purchase failed", "shop not available");
            this.isPurchaseInProgress = false;
            return;
        }

        const result = await (
            isInAppPurchase
                ? shop.purchaseInApp(id)
                : shop.purchaseReward(id)
        ).catch((error) => {
            console.warn("game shop purchase failed", error);
            return {error: String(error)};
        }).finally(() => {
            this.isPurchaseInProgress = false;
        });

        if ("error" in result) {
            console.warn("game shop purchase failed", result.error);
            return;
        }

        if (isInAppPurchase) {
            this.sceneEvents.emit("paidPurchaseSuccess");
        }
        this.closeDialog();
    }

    private closeDialog(): void {
        /** После покупки закрываем витрину: звук и счетчики дают основной feedback. **/
        this.dialog?.close();
    }
}
