import {AlignMethod, layoutChain, makeAlign} from '@kvisaz/phaser-sugar';
import {getLocalizedText, ViewElementBuilder} from '../../assets';
import {openCommonModalInScene} from '../../common/game-core';
import {Anima, fitToSize, SceneEvents} from '../../common';
import {gameConfig} from '../../config';
import {IGameEvents} from '../events';

interface IProps {
    scene: Phaser.Scene;
}

/**
 * агент - копируй этот комментарий и его структуру для новых обработчиков
 *
 * ## сценарий
 * Диалог GameOver
 * - слушает событие сцены onGameOverDialogRequest
 * - вызывает диалог в новой сцене
 * - по нажатию кнопок выполняет перезапуск игры или выход на стартовый экран
 *
 * ## идеология
 * Все в 1 файле!
 * - конструктор - кэшируем создание которое можно кэшировть, подписки
 * - openDialog
 * - createDialog
 * - элементарная графика берется из ViewElementBuilder
 *
 * Фокусируй диалоги таким образом - обработчик и создатель в одном файле!
 * ViewElementBuilder должен хранить простые хелперы
 *
 * наследование от Zone сделано для совместимости очистки на destroy
 * **/
export class SpiderGameOverDialogManager extends Phaser.GameObjects.Zone {
    private readonly unSubs: Array<() => void> = [];

    constructor(private props: IProps) {
        super(props.scene, 0, 0);
        const sceneEvents = new SceneEvents<IGameEvents>({scene: props.scene});
        this.unSubs.push(sceneEvents.on("onGameOverDialogRequest", this.openDialog.bind(this)));

        this.testRender();

    }

    destroy(fromScene?: boolean) {
        this.unSubs.forEach((unSub) => unSub());
        this.unSubs.length = 0;
        super.destroy(fromScene);
    }

    private testRender() {
        const {scene} = this.props;
        const testData: { score: number, coins: number } = {
            score: 1000,
            coins: 10
        }
        const dialog = this.createDialog(scene, testData);
        makeAlign(align => align.anchorSceneScreen(scene).center(dialog));
    }

    openDialog(data: { score: number, coins: number }) {
        const {scene} = this.props;
        const animationDuration = gameConfig.dialogs?.animationShowDuration ?? 180;

        /** запускаем диалог в новой сцене **/
        openCommonModalInScene({
            parentScene: scene,
            createContent: (scene) => this.createDialog(scene, data),
            props: {
                animationDuration,
                isCloseOnOverlayClick: true
            },
        });
    }

    createDialog(scene: Phaser.Scene, data: { score: number, coins: number }) {
        const parentSceneEvents = new SceneEvents<IGameEvents>({scene: this.props.scene});
        const builder = new ViewElementBuilder(scene);

        const container = scene.add.container(0, 0, []);
        const bg = builder.dialogBgLightNine({width: 910, height: 520});

        /** title **/
        const titleText = getLocalizedText('gameOver.congratulation');
        const textStyle: Phaser.Types.GameObjects.Text.TextStyle = {
            fontFamily: builder.getFontFamilyRusso(),
            fontSize: `${48}px`,
            color: '#FFB100',
        };
        const title = new Phaser.GameObjects.Text(this.scene, 0, 0, titleText, textStyle);

        /** инфо **/
        const infoTextStyle: Phaser.Types.GameObjects.Text.TextStyle = {
            fontFamily: builder.getFontFamilyRegular(),
            fontSize: `${48}px`,
            color: '#000000',
        };
        const scoreText = getLocalizedText('gameOver.scorePrefix') + ' ' + data.score;
        const scoreInfo = new Phaser.GameObjects.Text(this.scene, 0, 0, scoreText, infoTextStyle);

        const coinText = getLocalizedText('gameOver.coinsPrefix') + ' ' + data.coins;
        const coinsInfo = new Phaser.GameObjects.Text(this.scene, 0, 0, coinText, infoTextStyle);
        const coinIcon = builder.getCoin();
        fitToSize({
            gameObject: coinIcon,
            width: 55,
            height: 55
        })
        const coinTextGroup = layoutChain({
            children: [coinsInfo, coinIcon],
            alignToAnchor: AlignMethod.CENTER_Y,
            alignToNext: AlignMethod.RIGHT_TO,
            nextOffsetX: 5
        })

        const infoGroup = layoutChain({
            children: [scoreInfo, coinTextGroup],
            alignToAnchor: AlignMethod.CENTER_X,
            alignToNext: AlignMethod.BOTTOM_TO,
            nextOffsetX: 5
        })


        /** кнопки **/
        const newGameButtonLabel = getLocalizedText('spider.gameOver.newGame');
        const newGameButton = builder.buttonGreen(newGameButtonLabel, () => {
            /** событие передается в сцену текущую то есть открытую **/
            parentSceneEvents.emit('onGameOverNewGameClick')
        }, {
            width: 340
        });

        const exitButtonLabel = getLocalizedText('spider.gameOver.selectMode');
        const exitButton = builder.buttonYellow(exitButtonLabel, () => {
            /** событие передается в сцену текущую то есть открытую **/
            parentSceneEvents.emit('onGameOverExitClick')
        }, {
            width: 440
        });

        const buttonGroup = layoutChain({
            children: [newGameButton, exitButton],
            alignToAnchor: AlignMethod.CENTER_X,
            alignToNext: AlignMethod.BOTTOM_TO,
            nextOffsetY: 15
        })

        /** коты **/
        const {black, red} = builder.getCatHeroes();

        makeAlign(align => {
            align.anchor(bg);
            align.centerX(title).topIn(title, 25)
            align.centerX(buttonGroup).bottomIn(buttonGroup, -30)
            align.leftIn(black, -240).centerY(black, 10)
            align.rightIn(red, 240).centerY(red, 10);
            align.centerX(infoGroup).topIn(infoGroup, 125);
        })

        container.add([
            bg, newGameButton, exitButton, title, red, black, coinsInfo, coinIcon, scoreInfo
        ])
        return container;
    }
}
